"""Continuous offset-envelope bounds on an interval of an existing cubic table.

The polynomial is never refitted. Bernstein bounds cover velocity projection
and the cubic curvature numerator over each clipped certification interval.
"""
import bpy
from . import curved_corner_nodes as c


def build(*,polyline=False):
    name='Prochitecture Streets / Existing cubic interval envelope v1'
    if polyline:name+=' / Exact frames v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name);g.socket('Path','NodeSocketGeometry')
    for key in ('Start','End','Reach'):g.socket(key,'NodeSocketFloat')
    g.socket('Valid','NodeSocketBool','OUTPUT')
    for key in ('Speed Lower','Offset Speed Lower','Curvature Upper'):g.socket(key,'NodeSocketFloat','OUTPUT')
    inp=g.node('NodeGroupInput');path=inp.outputs['Path'];n=c._count(g,path)
    exact=c._read(g,path,'st_cc_polyline',0,'BOOLEAN') if polyline else False
    steps=c.choose(g,exact,1.,64.) if polyline else 64.
    index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);segment=g.math('FLOOR',index/steps)
    sub=g.math('MODULO',index,steps)
    read=lambda key,kind='FLOAT':c._read(g,path,'st_cc_'+key,segment,kind)
    span=g.math('MAXIMUM',read('span'),1e-12);knot=read('knot')
    lower=g.math('MAXIMUM',sub/steps,(c.V(g,inp.outputs['Start'])-knot)/span)
    upper=g.math('MINIMUM',(sub+1.)/steps,(c.V(g,inp.outputs['End'])-knot)/span)
    active=g.math('GREATER_THAN',upper,lower)
    a,b,d=[c._vec(g,read(key,'FLOAT_VECTOR')) for key in ('a','b','c')]
    velocity=lambda t:c._add(a,c._scale(c._add(c._scale(b,2.),c._scale(d,3.*t)),t))
    acceleration=lambda t:c._add(c._scale(b,2.),c._scale(d,6.*t))
    v0,v2=velocity(lower),velocity(upper);acc0,acc1=acceleration(lower),acceleration(upper)
    v1=c._add(v0,c._scale(acc0,.5*(upper-lower)))
    axis=c._unit(g,velocity(.5*(lower+upper)))
    speed=g.math('MINIMUM',c._dot(v0,axis),g.math('MINIMUM',c._dot(v1,axis),c._dot(v2,axis)))
    numerator=[c._cross(v0,acc0),(2.*c._cross(v1,acc0)+c._cross(v0,acc1))/3.,
        (c._cross(v2,acc0)+2.*c._cross(v1,acc1))/3.,c._cross(v2,acc1)]
    bound=g.math('MAXIMUM',g.math('MAXIMUM',g.math('ABSOLUTE',numerator[0]),g.math('ABSOLUTE',numerator[1])),
        g.math('MAXIMUM',g.math('ABSOLUTE',numerator[2]),g.math('ABSOLUTE',numerator[3])))
    curvature=bound/(g.math('MAXIMUM',speed,1e-12)**3.)
    rho=speed/span;jacobian=1.-c.V(g,inp.outputs['Reach'])*curvature
    offset_speed=rho*jacobian
    if polyline:
        # On an Exact leg M(s)=a(s)T+N and M'=kT. For a variable
        # offset d(s), F'=(1+d*k)T+d'*M. Projecting perpendicular to
        # M eliminates d', hence |F'| >= (1-reach*|k|)/max|M|.
        # M is linear, so its maximum norm on the clipped leg occurs at
        # an endpoint. This certifies the entire leg without sampling it.
        frame=c._vec(g,read('miter','FLOAT_VECTOR'))
        rate=c._vec(g,read('miter_rate','FLOAT_VECTOR'))
        tangent=c._unit(g,a)
        frame0=c._add(frame,c._scale(rate,lower*span))
        frame1=c._add(frame,c._scale(rate,upper*span))
        frame_bound=g.math('MAXIMUM',c._length(g,frame0),c._length(g,frame1))
        exact_jacobian=1.-c.V(g,inp.outputs['Reach'])*g.math('ABSOLUTE',c._dot(rate,tangent))
        offset_speed=c.choose(g,exact,exact_jacobian/g.math('MAXIMUM',frame_bound,1e-12),offset_speed)
        rho=c.choose(g,exact,1.,rho)
        jacobian=c.choose(g,exact,exact_jacobian,jacobian)
        # Zero is one-sided leg curvature; authored bends remain creases.
        curvature=c.choose(g,exact,0.,curvature)
    points=c._line(g,steps*g.math('MAXIMUM',1.,g.math('MINIMUM',n-1.,c.MAX_CONTROLS-1)))
    valid=g.math('GREATER_THAN',n,1.5)*g.math('LESS_THAN',n,c.MAX_CONTROLS+.5)
    start,end,reach=[c.V(g,inp.outputs[k]) for k in ('Start','End','Reach')]
    valid=valid*g.math('GREATER_THAN',start,-1e-6)*g.math('GREATER_THAN',end-start,1e-5)
    length=c._read(g,path,'st_cc_knot',n-1.)
    valid=valid*g.math('LESS_THAN',end,length+1e-5)*g.math('GREATER_THAN',reach,-1e-6)
    valid=valid*c._stat(g,points,c.choose(g,active,
        g.math('GREATER_THAN',rho,1e-5)*g.math('GREATER_THAN',jacobian,.02),1.))
    out=g.node('NodeGroupOutput')
    for key,value in (('Valid',valid),('Speed Lower',c._stat(g,points,c.choose(g,active,rho,1e8))),
        ('Offset Speed Lower',c._stat(g,points,c.choose(g,active,offset_speed,1e8))),
        ('Curvature Upper',c._stat(g,points,c.choose(g,active,curvature,0.),'Max'))):g.bind(value,out.inputs[key])
    return g.g


def certify(g,path,start,end,reach,*,polyline=False):
    node=g.node('GeometryNodeGroup','Bound the existing curve throughout the finite transition')
    node.node_tree=build(polyline=polyline)
    for key,value in (('Path',path),('Start',start),('End',end),('Reach',reach)):g.bind(value,node.inputs[key])
    return node
